import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import io.netty.channel.Channel;
import org.traccar.Protocol;
import org.traccar.model.Position;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import java.net.SocketAddress;
import java.util.TimeZone;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

@RunWith(MockitoJUnitRunner.class)
public class Gt06ProtocolDecoderTest {

    @Mock
    private Protocol protocol;

    @Mock
    private Channel channel;

    @Mock
    private SocketAddress address;

    private Gt06ProtocolDecoder getDecoder() {
        return new Gt06ProtocolDecoder(protocol);
    }

    @Test
    public void decodeGpsWithLengthScenarioTest() {
        Gt06ProtocolDecoder decoder = getDecoder();
        Position position = new Position();
        ByteBuf buf = Unpooled.buffer();

        assertFalse(decoder.decodeGps(position, buf, true, TimeZone.getDefault()));
    }

    @Test
    public void decodeGpsWithoutLengthScenarioTest() {
        Gt06ProtocolDecoder decoder = getDecoder();
        Position position = new Position();
        ByteBuf buf = Unpooled.buffer();

        assertFalse(decoder.decodeGps(position, buf, false, TimeZone.getDefault()));
    }

    @Test
    public void decodeGpsWithLengthAndSatellitesScenarioTest() {
        Gt06ProtocolDecoder decoder = getDecoder();
        Position position = new Position();
        ByteBuf buf = Unpooled.buffer();

        assertFalse(decoder.decodeGps(position, buf, true, true, true, TimeZone.getDefault()));
    }

    @Test
    public void decodeGpsWithLengthWithSatellitesWithSpeedScenarioTest() {
        Gt06ProtocolDecoder decoder = getDecoder();
        Position position = new Position();
        ByteBuf buf = Unpooled.buffer();

        assertFalse(decoder.decodeGps(position, buf, true, true, true, TimeZone.getDefault()));
    }

    @Test
    public void decodeGpsWithLengthWithoutSatellitesWithoutSpeedScenarioTest() {
        Gt06ProtocolDecoder decoder = getDecoder();
        Position position = new Position();
        ByteBuf buf = Unpooled.buffer();

        assertFalse(decoder.decodeGps(position, buf, true, false, false, TimeZone.getDefault()));
    }

    @Test
    public void decodeTest() throws Exception {
        Gt06ProtocolDecoder decoder = getDecoder();

        assertFalse(decoder.decode(channel, address, "test message instance"));
    }

    @Test(expected = Exception.class)
    public void decodeWithExceptionTest() throws Exception {
        Gt06ProtocolDecoder decoder = getDecoder();

        ByteBuf msg = Mockito.mock(ByteBuf.class);
        Mockito.when(msg.readableBytes()).thenThrow(new Exception());

        decoder.decode(channel, address, msg);
    }
}
